import sys
input = sys.stdin.read
data = input().split()

index = 0
T = int(data[index])
index += 1

results = []

for _ in range(T):
    Q = int(data[index])
    index += 1
    S = set()
    E = 0
    O = 0

    for _ in range(Q):
        X = int(data[index])
        index += 1

        if X not in S:
            S.add(X)
            if bin(X).count('1') % 2 == 0:
                E += 1
            else:
                O += 1

            new_elements = set()
            for y in S:
                if y != X:
                    z = y ^ X
                    if z not in S:
                        new_elements.add(z)

            for z in new_elements:
                S.add(z)
                if bin(z).count('1') % 2 == 0:
                    E += 1
                else:
                    O += 1

        results.append(f"{E} {O}")

print("\n".join(results))
